import{_ as e}from"./chunks/03-workers.BW4p8Tw4.js";import{_ as t,o as c,c as d,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"워커","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/worker"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/worker"}],["meta",{"property":"og:title","content":"워커"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/worker.md","filePath":"docs/worker.md"}'),a={name:"docs/worker.md"};function n(l,o,i,s,p,h){return c(),d("div",null,[...o[0]||(o[0]=[r('<h1 id="워커" tabindex="-1">워커 <a class="header-anchor" href="#워커" aria-label="Permalink to &quot;워커&quot;">​</a></h1><p><strong>워커는 30초마다 깨어나 큐를 훑고, 열려 있는 티켓 하나를 물어 세션을 띄우는 셸 스크립트입니다.</strong> 파일 하나가 워커 하나이고(<code>&lt;루트&gt;/workers/&lt;이름&gt;.sh</code>), 첫 프로젝트를 만들 때 <code>w1</code>이 이미 섰습니다.</p><h2 id="워커-화면-—-한-줄이-말하는-것" tabindex="-1">워커 화면 — 한 줄이 말하는 것 <a class="header-anchor" href="#워커-화면-—-한-줄이-말하는-것" aria-label="Permalink to &quot;워커 화면 — 한 줄이 말하는 것&quot;">​</a></h2><p>왼쪽 내비의 <code>워커</code>. 한 줄이 워커 하나이고, 그 줄만 읽어도 지금 무슨 일이 벌어지는지 압니다.</p><p><img src="'+e+'" alt="dira 워커 화면. 이름·상태·물고 있는 티켓·pid·엔진·마지막 활동이 표로 나열돼 있습니다."></p><ul><li><strong>상태</strong>는 넷입니다. <code>running</code>은 세션을 띄워 놓고 끝나기를 기다리는 중, <code>idle</code>은 cron에 걸려 있고 지금은 아무것도 안 물고 있는 상태입니다. <code>stopped</code>은 crontab에서 빠져 있어 아예 깨어나지 않고(배지 옆에 <code>crontab 미등록</code>이 붙습니다), <code>stale</code>은 세션 프로세스가 죽었는데 자리만 남은 것입니다.</li><li><strong>물고 있는 티켓</strong>은 지금 잡고 있는 티켓의 해시입니다. 누르면 그 티켓 상세로 갑니다.</li><li><strong>pid</strong>는 지금 그 워커를 돌리고 있는 프로세스의 번호입니다. <code>running</code>과 <code>stale</code>은 이 번호가 살아 있는지로 갈립니다(<a href="/docs/screens">화면 소개</a> §워커).</li><li><strong>토큰(5시간)</strong> 열은 최근 5시간 안에 끝난 세션이 쓴 토큰 합입니다. 한도는 워커별이 아니라 계정 하나에 붙어 있어서, 이 열이 한 통을 누가 얼마나 먹었는지를 보여 줍니다.</li><li><strong>엔진</strong>은 이 워커가 티켓을 넘길 CLI입니다. 값을 누르면 그 자리에서 바꿀 수 있고, 아래 §<code>엔진</code> 열에서 다룹니다.</li><li><strong>마지막 활동</strong>은 <code>runner.log</code>에 이 워커 이름으로 마지막에 찍힌 줄 그대로입니다. <code>DISPATCH</code>면 방금 티켓 하나를 세션에 넘긴 것이고, <code>SKIP</code>이면 깨어났는데 앞 세션이 아직 안 끝나 그냥 돌아간 것입니다.</li></ul><h2 id="_30초-주기-—-깨어났다-죽는-스크립트" tabindex="-1">30초 주기 — 깨어났다 죽는 스크립트 <a class="header-anchor" href="#_30초-주기-—-깨어났다-죽는-스크립트" aria-label="Permalink to &quot;30초 주기 — 깨어났다 죽는 스크립트&quot;">​</a></h2><p>워커는 늘 떠 있는 프로세스가 아닙니다. cron이 30초에 한 번 그 스크립트를 처음부터 실행하고, 스크립트는 할 일을 마치면 죽습니다. 물 티켓이 없으면 큐를 훑고 그 자리에서 끝나며 로그에도 아무것도 안 남깁니다.</p><p>그래서 <code>idle</code>은 &quot;차례를 기다리는 중&quot;이 아닙니다. <strong>지금 이 순간 그 워커의 프로세스가 아예 없다</strong>는 뜻이고, 다음 :00이나 :30에 새 프로세스가 하나 뜹니다. 그 30초는 crontab에 들어간 줄 둘이 만듭니다(아래 §새 워커에 딸려 오는 것 다섯). 화면에 조절할 칸이 없는 것도 그래서입니다.</p><p>앱과는 무관하게 돕니다. 앱을 닫아도 티켓은 계속 처리되고, 켜 둔다고 더 빨리 돌지도 않습니다. 반대로 <code>중단</code>으로 crontab 줄을 빼면 앱이 떠 있어도 그 워커는 다시 깨어나지 않습니다.</p><h2 id="워커와-세션-—-한-번에-티켓-하나" tabindex="-1">워커와 세션 — 한 번에 티켓 하나 <a class="header-anchor" href="#워커와-세션-—-한-번에-티켓-하나" aria-label="Permalink to &quot;워커와 세션 — 한 번에 티켓 하나&quot;">​</a></h2><p>티켓을 잡은 워커가 그다음에 하는 일은 세션을 띄우는 것입니다. 세션은 그 티켓을 들고 도는 에이전트 프로세스이고(기본은 <code>claude -p</code>), 페르소나 프로필과 협업 프로토콜, 티켓 본문을 이어 붙인 프롬프트를 받습니다. <strong>워커는 그 세션이 끝날 때까지 같은 자리에서 기다립니다.</strong> 30분이 걸리는 티켓이면 30분을 기다립니다.</p><p>기다리는 동안에도 cron은 30초마다 그 워커를 부릅니다. 새로 뜬 쪽은 앞 실행이 아직 일하는 중인 것을 보고 <code>SKIP</code> 한 줄만 남기고 물러납니다. 한 워커가 세션 둘을 띄우는 일도, 같은 티켓이 두 번 디스패치되는 일도 그래서 없습니다. 그 자리를 막는 장치와 그것이 워커 수와 어떻게 이어지는지는 <a href="/docs/concurrency">동시에 몇 개 돌릴까</a> §워커 락에 있습니다.</p><p>워커는 짧게 살고 세션은 오래 삽니다. <code>running</code>이 한참 서 있다면 그 워커가 띄운 세션이 아직 일하는 중이라는 뜻입니다. 지금 그 세션에 할 말이 있으면 <a href="/docs/barge-in">도는 세션에 말 걸기</a>로 가세요.</p><h2 id="티켓을-무는-일-—-파일-이름-하나-바꾸기" tabindex="-1">티켓을 무는 일 — 파일 이름 하나 바꾸기 <a class="header-anchor" href="#티켓을-무는-일-—-파일-이름-하나-바꾸기" aria-label="Permalink to &quot;티켓을 무는 일 — 파일 이름 하나 바꾸기&quot;">​</a></h2><p>&quot;문다&quot;는 비유가 아닙니다. 후보를 고른 워커가 실제로 하는 동작은 <code>&lt;해시&gt;.md</code>를 <code>&lt;해시&gt;.wip.md</code>로 만드는 것 하나입니다. 성공하면 그 티켓은 이 워커 것이 되고, 이미 다른 워커가 바꿔 놨으면 그 자리에서 실패해 다음 후보로 넘어갑니다.</p><p>워커 여럿이 같은 큐를 동시에 봐도 둘이 같은 티켓을 물지 않는 이유가 이것입니다. 확인하는 순간이 곧 잡는 순간이라 그 사이에 다른 워커가 끼어들 틈이 없습니다. 이름 바꾸기가 어떻게 락이 되는지는 <a href="/docs/states">티켓이 지나는 상태</a> §파일명이 곧 락인 이유에 있습니다.</p><p>후보를 고르는 순서는 만든 날짜순입니다. 열려 있고 선행 티켓(<code>deps</code>)이 다 끝난 것 중 가장 오래된 하나를 집습니다.</p><h2 id="워커마다-트리가-따로인-이유" tabindex="-1">워커마다 트리가 따로인 이유 <a class="header-anchor" href="#워커마다-트리가-따로인-이유" aria-label="Permalink to &quot;워커마다 트리가 따로인 이유&quot;">​</a></h2><p>두 세션이 한 디렉터리에서 같은 브랜치에 커밋하면 서로의 작업을 덮습니다. 이 프로젝트에서 실제로 났던 사고입니다. 새 워커가 템플릿 워커의 작업 디렉터리 값을 그대로 물려받는 바람에 세 세션이 한 트리에서 한 브랜치에 커밋하고 있었고, 화면은 그걸 결함으로 보여주지도 못했습니다.</p><p>그래서 지금은 그 경로를 워커 이름에서 유도합니다. 이름이 곧 디렉터리라서 두 워커가 같은 트리를 가리키는 값이 애초에 생기지 않습니다.</p><p>프로젝트 폴더를 git이 관리하고 있지 않으면 트리는 만들지 않고 그 사실만 알립니다. 워커 파일도 crontab 등록도 그대로 유효합니다. 워커가 하나뿐인 배치에는 트리가 필요 없습니다.</p><h2 id="워커-생성-한-번" tabindex="-1"><code>워커 생성</code> 한 번 <a class="header-anchor" href="#워커-생성-한-번" aria-label="Permalink to &quot;`워커 생성` 한 번&quot;">​</a></h2><p>워커 하나가 한 번에 티켓 하나만 뭅니다. 그래서 대기 레인에는 티켓이 쌓이는데 진행중 레인이 늘 한 장이면, 그 워커로는 부족해진 것입니다. 늘리는 자리는 워커 화면입니다(<a href="/docs/concurrency">동시에 몇 개 돌릴까</a> 참고).</p><p>우상단 <code>워커 생성</code>을 누르면 다이얼로그에서 정할 것이 둘뿐입니다.</p><ul><li><strong>이름</strong> — <code>w2</code>처럼 짧게 지으세요. 이 이름이 그대로 파일명이자 작업 디렉터리 이름이 됩니다.</li><li><strong>엔진·모델</strong> — <code>claude</code>와 <code>codex</code> 중 하나, 그 안에서 모델을 고릅니다. 기본값은 <code>claude</code> + <code>모델 지정 안 함</code>이고, 엔진 CLI의 자기 기본값을 쓰겠다는 뜻입니다. 목록에 없는 모델 이름은 <code>직접 입력…</code>으로 넣으세요.</li></ul><p>성공 화면에 등록 명령어가 없다는 것이 이 동작의 전부입니다. 만들었다는 문장과 <code>crontab에 등록했습니다 — 30초 뒤부터 티켓을 물어갑니다.</code>가 뜨고, 목록의 그 워커는 <code>stopped</code>가 아니라 <code>idle</code>로 섭니다. 셸을 열 일이 없습니다.</p><h3 id="새-워커에-딸려-오는-것-다섯" tabindex="-1">새 워커에 딸려 오는 것 다섯 <a class="header-anchor" href="#새-워커에-딸려-오는-것-다섯" aria-label="Permalink to &quot;새 워커에 딸려 오는 것 다섯&quot;">​</a></h3><ol><li><strong>워커 파일</strong> <code>&lt;루트&gt;/workers/&lt;이름&gt;.sh</code>. 기존 워커를 템플릿으로 복사하고 755로 둡니다.</li><li><strong>crontab 두 줄</strong> — <code>:00</code>과 <code>:30</code>. cron은 정해 둔 시각마다 명령을 대신 실행해 주는 macOS의 기본 기능이고, crontab은 그 예약 목록입니다. 워커 하나에 두 줄인 이유는 cron이 다룰 수 있는 가장 잔 단위가 분이라서입니다.</li><li><strong>git 워크트리</strong> <code>&lt;루트&gt;/worktrees/&lt;이름&gt;</code>과 브랜치 <code>wt/&lt;이름&gt;</code>. 브랜치는 같은 코드에서 갈라져 나온 작업 갈래고, 워크트리는 그 갈래를 따로 펼쳐 둔 폴더입니다. 워커마다 자기 폴더 안에서 자기 갈래로 일한다고 보시면 됩니다.</li><li><strong><code>.dira</code> 심링크</strong> — 그 워크트리 안에서 큐를 가리키는 바로가기입니다. 세션이 <code>.dira/tickets/…</code>를 상대경로로 쓰기 때문에 이게 없으면 워커가 자기 티켓을 찾지 못합니다.</li><li><strong>검증.</strong> 그 심링크를 되짚어 이 프로젝트의 큐로 풀리는지까지 확인합니다. 링크가 걸려 있다는 것만 보고 넘어가지 않습니다.</li></ol><p>의존성 설치(<code>npm install</code> 같은 것)는 하지 않습니다. 이게 이 기능의 천장입니다. 새 워커의 작업 디렉터리에서 프론트엔드 티켓을 처음 물면 <code>node_modules</code>가 없습니다. 프로젝트마다 명령이 달라서 앱이 알 방법이 없습니다.</p><h2 id="중단-·-재등록-·-삭제" tabindex="-1">중단 · 재등록 · 삭제 <a class="header-anchor" href="#중단-·-재등록-·-삭제" aria-label="Permalink to &quot;중단 · 재등록 · 삭제&quot;">​</a></h2><p>행 오른쪽 버튼 셋이고, 셋이 건드리는 것이 서로 다릅니다.</p><table tabindex="0"><thead><tr><th>버튼</th><th>하는 일</th><th>남는 것</th></tr></thead><tbody><tr><td><code>중단</code></td><td>crontab에서 그 워커 줄을 뺍니다</td><td>파일과 작업 디렉터리는 그대로입니다</td></tr><tr><td><code>재등록</code></td><td>crontab 줄을 다시 넣습니다</td><td><code>중단</code>의 정확한 역방향이고 그것뿐입니다</td></tr><tr><td><code>삭제</code></td><td>crontab 줄을 뺀 뒤에 파일을 지웁니다</td><td>티켓은 하나도 지워지지 않습니다</td></tr></tbody></table><ul><li><code>중단</code>과 <code>재등록</code>은 같은 자리에 있고 동시에 뜨지 않습니다. 판정은 상태가 아니라 crontab이 합니다. 뺄 줄이 있으면 <code>중단</code>, 없으면 <code>재등록</code>입니다.</li><li><code>중단</code>은 도는 세션을 죽이지 않습니다. 지금 티켓을 물고 있으면 그 티켓이 끝난 뒤 멈춘다고 알려 줍니다.</li><li><code>삭제</code>는 순서가 정해져 있습니다. crontab 먼저, 파일 나중입니다. 뒤집으면 그 1분 사이에 cron이 없는 파일을 실행해 로그에 에러가 쌓입니다. crontab 해제가 실패하면 파일을 지우지 않고 멈춥니다.</li><li><code>running</code>인 워커는 삭제가 막힙니다. 돌고 있는 세션과 그 세션이 잡아 둔 자리가 붕 뜨기 때문입니다. 먼저 중단하시고, 물고 있는 티켓이 끝난 뒤에 지우세요.</li></ul><h2 id="엔진-열-—-나중에-엔진·모델-바꾸기" tabindex="-1"><code>엔진</code> 열 — 나중에 엔진·모델 바꾸기 <a class="header-anchor" href="#엔진-열-—-나중에-엔진·모델-바꾸기" aria-label="Permalink to &quot;`엔진` 열 — 나중에 엔진·모델 바꾸기&quot;">​</a></h2><p><code>엔진</code> 열은 표시 전용이 아닙니다. 값을 누르면 생성 다이얼로그와 같은 폼이 열리고, 거기서 고른 엔진·모델이 그 워커 파일에 써집니다. 이미 만들어진 워커를 손으로 고칠 일이 없다는 뜻입니다.</p><ul><li><code>TICKET_ENGINE</code> 대입이 아직 없는 워커도 열립니다. 대부분의 기존 워커가 그 상태이고, <code>기본값 가정</code> 배지가 그 사실을 말해 줍니다.</li><li><code>codex</code> 워커는 참견과 세션 스트림이 없습니다. 그 엔진이 트랜스크립트를 남기지 않아서입니다. 고장이 아니라 기능 집합이 다른 것이고, 티켓 수행은 같습니다.</li></ul><h2 id="도중에-막혔을-때-—-남은-명령만-복사" tabindex="-1">도중에 막혔을 때 — 남은 명령만 복사 <a class="header-anchor" href="#도중에-막혔을-때-—-남은-명령만-복사" aria-label="Permalink to &quot;도중에 막혔을 때 — 남은 명령만 복사&quot;">​</a></h2><p>crontab 쓰기는 macOS에서 <code>앱 관리</code> 승인이 걸려 있어 막힐 수 있고, 워크트리는 이름이 겹치거나 권한에서 걸릴 수 있습니다. 그래도 앱은 되돌리지 않습니다. 어디까지 갔는지와 사유를 그 자리에 보여 주고, 아직 남은 명령만 복사 버튼으로 줍니다. 이미 끝난 단계를 다시 돌리면 오히려 함정을 밟습니다.</p><p>그 명령을 이 문서에 적어 두지 않는 이유가 이것입니다. 성공하면 안 보이고, 실패한 화면이 그때의 정확한 경로를 채워서 주니까요.</p><hr><p>앱 없이 워커를 손으로 만들고 cron에 직접 거는 절차는 부록 <a href="/docs/cron">엔진만으로 돌리기</a>에 있습니다.</p><p>다음은 <a href="/docs/concurrency">동시에 몇 개 돌릴까</a>입니다.</p>',43)])])}const b=t(a,[["render",n]]);export{m as __pageData,b as default};
